\begin{lemma}[Formalization support: a uniform point from the directly indexed law]
	\label{lem:qld-sublines-uniform-point}
	\lean{MIPStarRE.QPBT.uniformDistribution_map_uncurry}
	\lean{MIPStarRE.QPBT.uniformDistribution_map_directLine_add_smul}
	\lean{MIPStarRE.QPBT.avgOver_uniform_directLdSpace_line_add_smul}
	\lean{MIPStarRE.QPBT.avgOver_directLinePointDist_line_add_smul}
	\lean{MIPStarRE.QPBT.SubLineWitness.avgOver_projX_projZ}
	\leanok
	\uses{lem:qld-sublines, def:line-point-dist, def:line-representative,
		def:combine-map}
	Let $D_{\rm dir}$ be an auxiliary subline distribution whose extended-line
	marginal is the line marginal of the line-point law with coordinate indices
	sampled uniformly and directly. A uniform affine parameter on that
	extended line gives a uniform point of $\F_q^{2m+2}$, whose $x$ and $z$
	blocks are independent uniform points of $\F_q^m$. This statement uses
	directly sampled coordinate indices. Its transport to the source's
	seed-indexed distribution remains open
	(\cite{gap:qpbt_ld-dimension-divisibility}).
\end{lemma}
\begin{proof}
	\leanok
	For a fixed direction $v$, the map $(y,t)\mapsto L_v(y)+tv$ on
	ambient-point--parameter pairs has fibers of size $q$. If $v\ne0$,
	$y$ varies over a coset while $L_v(y)$ and $t$ are fixed; if $v=0$,
	$y$ is fixed and $t$ is free. The coordinate split and scalar
	identification are bijections.
\end{proof}

